// Bundled from public/brand/hawk-white.png so SMTP emails do not fetch a remote image.
export const HAWK_EMAIL_LOGO_CID =
  "hawk-brand-logo@hawkprofessional.vercel.app";
const logoBase64 =
  "";
export function hawkEmailLogoAttachment() {
  return {
    filename: "hawk-logo.png",
    content: Buffer.from(logoBase64, "base64"),
    contentType: "image/png",
    contentDisposition: "inline" as const,
    cid: HAWK_EMAIL_LOGO_CID,
  };
}
